/**
 * Terminal forensics missions. Players investigate real files in a disposable
 * shell on the VM; answers are checked here on the server, never inside the
 * container, so reading the case files can't reveal the answer key.
 *
 * Files are generated by sandbox/terminal/build_cases.py; keep them in sync.
 */

export type TerminalQuestion = {
  id: string;
  prompt: string;
  hint: string;
  placeholder: string;
  /** Index into skillNames (Sender, Links, Urgency, Authority, Requests, Attachments, Trust). */
  skill: number;
  accept: (answer: string) => boolean;
  explanation: string;
};

export type TerminalCase = { slug: "header-hunt" | "payload-autopsy"; questions: TerminalQuestion[] };

/** Hostnames: drop scheme, path and stray punctuation. */
const clean = (value: string) => value.trim().toLowerCase().replace(/^["'<]+|["'>.,]+$/g, "").replace(/^https?:\/\//, "").replace(/\/.*$/, "");

/** File names: the last path segment, without stray punctuation. */
const base = (value: string) => value.trim().toLowerCase().replace(/^["'<]+|["'>.,]+$/g, "").split("/").pop() ?? "";

