export type TerminalState = { answers: Record<string, { tries: number; correct: boolean }> };

export const newTerminalState = (): TerminalState => ({ answers: {} });

/** 25 XP per question first time, 15 after a wrong try; complete when all are solved. */
export function scoreTerminal(slug: TerminalCase["slug"], state: TerminalState) {
  const questions = TERMINAL_CASES[slug].questions;
  const points = questions.map(question => {
    const answer = state.answers[question.id];
    if (!answer?.correct) return 0;
    return answer.tries <= 1 ? 25 : 15;
  });
  const complete = questions.every(question => state.answers[question.id]?.correct);
  const skills = Array.from({ length: 7 }, () => [0, 0, 0]);
  for (const question of questions) {
    const answer = state.answers[question.id];
    skills[question.skill][1] += 1;
    if (answer?.correct && answer.tries <= 1) skills[question.skill][0] += 1;
    skills[question.skill][2] += Math.max(0, (answer?.tries ?? 0) - (answer?.correct ? 1 : 0));
  }
  return {
    complete,
    xp: points.reduce<number>((sum, value) => sum + value, 0),
    learning: { skills: skills.map(([found, available, wrong]) => [found, available, Math.min(wrong, 100)]), right: points.filter(value => value === 25).length, decisions: questions.length },
  };
}

/** What the browser may see: no answers, explanations only once solved. */
export function publicCase(slug: TerminalCase["slug"], state: TerminalState) {
  return TERMINAL_CASES[slug].questions.map(question => {
    const answer = state.answers[question.id];
    return {
      id: question.id, prompt: question.prompt, hint: question.hint, placeholder: question.placeholder,
      tries: answer?.tries ?? 0, correct: Boolean(answer?.correct),
      explanation: answer?.correct ? question.explanation : null,
    };
  });
}

export type PublicQuestion = ReturnType<typeof publicCase>[number];
